Rule.Source:
import java.text.SimpleDateFormat;
import java.util.*;
import sailpoint.api.ManagedAttributer;
import sailpoint.object.*;
import sailpoint.tools.Util;

int TRS_DAYS = 60;          // how far back to look
int TRS_MAX = 50;           // most requests shown at once
String TRS_ALL = "All";     // team member filter value for everyone
// Capabilities that get the "View as manager" picker, e.g. add "Help Desk".
// Either the name (SystemAdministrator) or the name shown in the UI (System Administrator) works.
List TRS_VIEW_AS_CAPABILITIES = Arrays.asList(new String[] { "System Administrator" });

/** Lower-cased with spaces removed, so "System Administrator" matches "SystemAdministrator". */
String trsCapKey(String s) {
    return (s == null) ? "" : s.replaceAll("\\s+", "").toLowerCase();
}

/** True if the person can view any manager's team. */
boolean trsCanViewAs(String launcherName) {
    Identity launcher = Util.isNullOrEmpty(launcherName) ? null : context.getObjectByName(Identity.class, launcherName);
    if (launcher == null) {
        return false;
    }
    Set wanted = new HashSet();
    for (Object cap : TRS_VIEW_AS_CAPABILITIES) {
        wanted.add(trsCapKey((String) cap));
    }
    for (Capability cap : Util.safeIterable(launcher.getCapabilityManager().getEffectiveCapabilities())) {
        if (wanted.contains(trsCapKey(cap.getName())) || wanted.contains(trsCapKey(cap.getDisplayableName()))) {
            return true;
        }
    }
    return false;
}

String trsDisplayName(Identity identity, String fallback) {
    if (identity == null) {
        return Util.isNullOrEmpty(fallback) ? "" : fallback;
    }
    return Util.isNullOrEmpty(identity.getDisplayName()) ? identity.getName() : identity.getDisplayName();
}

/** Display name for an identity or workgroup name. */
String trsNameToDisplay(String name) {
    if (Util.isNullOrEmpty(name)) {
        return "";
    }
    return trsDisplayName(context.getObjectByName(Identity.class, name), name);
}

/** The manager's direct reports as maps {id, name, displayName}, sorted by display name. */
List trsTeam(String managerName) {
    List team = new ArrayList();
    if (Util.isNullOrEmpty(managerName)) {
        return team;
    }
    QueryOptions qo = new QueryOptions();
    qo.addFilter(Filter.eq("manager.name", managerName));
    qo.setOrderBy("displayName");
    Iterator it = context.search(Identity.class, qo, "id,name,displayName");
    while (it.hasNext()) {
        Object[] row = (Object[]) it.next();
        Map m = new HashMap();
        m.put("id", row[0]);
        m.put("name", row[1]);
        m.put("displayName", Util.isNullOrEmpty((String) row[2]) ? row[1] : row[2]);
        team.add(m);
    }
    return team;
}

/** Open work items and archived (closed) work items for a request. */
List trsWorkItems(Class cls, String requestId) {
    QueryOptions qo = new QueryOptions();
    qo.addFilter(Filter.eq("identityRequestId", requestId));
    return context.getObjects(cls, qo);
}

String trsOwners(List items) {
    Set names = new LinkedHashSet();
    for (Object o : items) {
        if (o instanceof WorkItem) {
            WorkItem wi = (WorkItem) o;
            names.add(trsDisplayName(wi.getOwner(), null));
        } else {
            WorkItemArchive wa = (WorkItemArchive) o;
            String who = Util.isNullOrEmpty(wa.getCompleter()) ? wa.getOwnerName() : wa.getCompleter();
            names.add(trsNameToDisplay(who));
        }
    }
    names.remove("");
    return names.isEmpty() ? "the assigned team" : Util.join(new ArrayList(names), ", ");
}

List trsOfType(List items, WorkItem.Type type) {
    List out = new ArrayList();
    for (Object o : items) {
        WorkItem.Type t = (o instanceof WorkItem) ? ((WorkItem) o).getType() : ((WorkItemArchive) o).getType();
        if (t == type) {
            out.add(o);
        }
    }
    return out;
}

List trsFinished(List archived) {
    List out = new ArrayList();
    for (Object o : archived) {
        if (((WorkItemArchive) o).getState() == WorkItem.State.Finished) {
            out.add(o);
        }
    }
    return out;
}

String TRS_DONE = "Done";
String TRS_DONE_MANUAL = "Done (set up manually)";
String TRS_MANUAL = "Being set up manually";
String TRS_SENT = "Sent, waiting for the application to confirm";
String TRS_FAILED = "Failed";
String TRS_RETRY = "Retrying";
String TRS_REJECTED = "Rejected";
String TRS_APPROVAL = "Waiting on approval";
String TRS_IN_PROGRESS = "In progress";

/** One item's status in plain English. A failed item with a manual work item is being (or was) set up manually. */
String trsItemStatus(IdentityRequestItem item, List open, List archived) {
    if (item.isRejected()) {
        return TRS_REJECTED;
    }
    ApprovalItem.ProvisioningState ps = item.getProvisioningState();
    if (ps == ApprovalItem.ProvisioningState.Finished) {
        return TRS_DONE;
    }
    if (ps == ApprovalItem.ProvisioningState.Commited) {
        return TRS_SENT;
    }
    boolean manualOpen = !trsOfType(open, WorkItem.Type.ManualAction).isEmpty();
    if (ps == ApprovalItem.ProvisioningState.Failed || ps == ApprovalItem.ProvisioningState.Retry
            || ps == ApprovalItem.ProvisioningState.Unverifiable) {
        if (manualOpen) {
            return TRS_MANUAL;
        }
        if (!trsFinished(trsOfType(archived, WorkItem.Type.ManualAction)).isEmpty()) {
            return TRS_DONE_MANUAL;
        }
        return ps == ApprovalItem.ProvisioningState.Retry ? TRS_RETRY : TRS_FAILED;
    }
    if (manualOpen) {
        return TRS_MANUAL;
    }
    if (item.getApprovalState() == null || item.getApprovalState() == WorkItem.State.Pending) {
        return trsOfType(open, WorkItem.Type.Approval).isEmpty() ? TRS_IN_PROGRESS : TRS_APPROVAL;
    }
    return TRS_IN_PROGRESS;
}

/** The approvers who rejected items on the request, by display name. */
String trsRejectors(IdentityRequest req) {
    List rejectors = new ArrayList();
    for (IdentityRequestItem item : Util.safeIterable(req.getItems())) {
        if (item.isRejected() && !Util.isNullOrEmpty(item.getApproverName())) {
            String who = trsNameToDisplay(item.getApproverName());
            if (!rejectors.contains(who)) {
                rejectors.add(who);
            }
        }
    }
    return Util.join(rejectors, ", ");
}

/**
 * The request's status in plain English, from its open/closed work items and its items' statuses
 * (itemStatuses: the trsItemStatus of each item; sentApps: applications with items waiting to confirm).
 */
String trsStatus(IdentityRequest req, List open, List archived, List itemStatuses, Set sentApps) {
    String id = Util.stripLeadingChar(req.getName(), '0');
    if (req.getExecutionStatus() == IdentityRequest.ExecutionStatus.Terminated) {
        return "Cancelled";
    }

    List openManual = trsOfType(open, WorkItem.Type.ManualAction);
    if (!openManual.isEmpty()) {
        return "In progress: being set up manually by " + trsOwners(openManual);
    }
    List openApproval = trsOfType(open, WorkItem.Type.Approval);
    if (!openApproval.isEmpty()) {
        return "Waiting on approval from " + trsOwners(openApproval);
    }
    if (!open.isEmpty()) {
        return "Waiting on " + trsOwners(open);
    }

    if (itemStatuses.isEmpty()) {
        IdentityRequest.CompletionStatus cs = req.getCompletionStatus();
        if (cs == IdentityRequest.CompletionStatus.Success) {
            return TRS_DONE;
        }
        if (cs == IdentityRequest.CompletionStatus.Failure) {
            return "Failed: contact the helpdesk with request #" + id;
        }
        return TRS_IN_PROGRESS;
    }

    boolean anyDone = itemStatuses.contains(TRS_DONE) || itemStatuses.contains(TRS_DONE_MANUAL) || itemStatuses.contains(TRS_SENT);
    if (itemStatuses.contains(TRS_FAILED)) {
        return (anyDone ? "Partly done" : "Failed") + ": contact the helpdesk with request #" + id;
    }
    if (itemStatuses.contains(TRS_RETRY)) {
        return "In progress: the application didn't respond, IdentityIQ will retry automatically";
    }
    if (itemStatuses.contains(TRS_IN_PROGRESS) || itemStatuses.contains(TRS_APPROVAL) || itemStatuses.contains(TRS_MANUAL)) {
        return TRS_IN_PROGRESS;
    }

    String rejectedBy = trsRejectors(req);
    if (!anyDone) {
        return Util.isNullOrEmpty(rejectedBy) ? "Rejected" : "Rejected by " + rejectedBy;
    }
    String prefix;
    if (itemStatuses.contains(TRS_SENT)) {
        prefix = "Sent to " + Util.join(new ArrayList(sentApps), ", ") + ", waiting for it to confirm (usually after the next sync)";
    } else if (itemStatuses.contains(TRS_DONE_MANUAL)) {
        prefix = "Done (set up manually by " + trsOwners(trsFinished(trsOfType(archived, WorkItem.Type.ManualAction))) + ")";
    } else {
        prefix = TRS_DONE;
    }
    if (itemStatuses.contains(TRS_REJECTED)) {
        return prefix + "; some items were rejected" + (Util.isNullOrEmpty(rejectedBy) ? "" : " by " + rejectedBy);
    }
    return prefix;
}

String trsItemLabel(IdentityRequestItem item) {
    String op = item.getOperation();
    String verb = "Remove".equals(op) ? "Remove" : ("Create".equals(op) ? "New account" : "Add");
    String app = item.getApplication();
    if ("IIQ".equals(app) || Util.isNullOrEmpty(app)) {
        app = "Role";
    }
    Object value = item.getValue();
    String what = (value == null) ? "" : value.toString();
    if (!Util.isNullOrEmpty(what) && !"Role".equals(app) && !Util.isNullOrEmpty(item.getName())) {
        Application application = context.getObjectByName(Application.class, app);
        ManagedAttribute ma = (application == null) ? null
                : ManagedAttributer.get(context, application.getId(), item.getName(), what);
        if (ma != null && !Util.isNullOrEmpty(ma.getDisplayableName())) {
            what = ma.getDisplayableName();
        }
    }
    if (Util.isNullOrEmpty(what)) {
        return verb + ": " + app;
    }
    return verb + ": " + app + " - " + what;
}

/**
 * Recent requests for the manager's direct reports, newest first.
 * memberName narrows it to one direct report (ignored unless that person really reports to the manager).
 * Each row: {id, person, requester, created, status, items: List of {label, status}}.
 */
List trsRequests(String managerName, String memberName) {
    List rows = new ArrayList();
    List ids = new ArrayList();
    for (Object o : trsTeam(managerName)) {
        Map m = (Map) o;
        if (Util.isNullOrEmpty(memberName) || TRS_ALL.equals(memberName) || memberName.equals(m.get("name"))) {
            ids.add(m.get("id"));
        }
    }
    if (ids.isEmpty()) {
        return rows;
    }

    Calendar cutoff = Calendar.getInstance();
    cutoff.add(Calendar.DAY_OF_MONTH, -TRS_DAYS);
    QueryOptions qo = new QueryOptions();
    qo.addFilter(Filter.in("targetId", ids));
    qo.addFilter(Filter.ge("created", cutoff.getTime()));
    qo.addOrdering("created", false);
    qo.setResultLimit(TRS_MAX);

    SimpleDateFormat fmt = new SimpleDateFormat("MMM d, yyyy");
    for (Object o : context.getObjects(IdentityRequest.class, qo)) {
        IdentityRequest req = (IdentityRequest) o;
        List open = trsWorkItems(WorkItem.class, req.getName());
        List archived = trsWorkItems(WorkItemArchive.class, req.getName());

        List items = new ArrayList();
        List itemStatuses = new ArrayList();
        Set sentApps = new LinkedHashSet();
        for (IdentityRequestItem item : Util.safeIterable(req.getItems())) {
            // Expansions and account attributes ("Set") are details of another item; the "New account" line covers them.
            if (item.isExpansion() || "Set".equals(item.getOperation())) {
                continue;
            }
            String st = trsItemStatus(item, open, archived);
            if (TRS_SENT.equals(st)) {
                sentApps.add(item.getApplication());
            }
            itemStatuses.add(st);
            Map im = new HashMap();
            im.put("label", trsItemLabel(item));
            im.put("status", st);
            items.add(im);
        }

        Map row = new HashMap();
        row.put("id", Util.stripLeadingChar(req.getName(), '0'));
        row.put("person", req.getTargetDisplayName());
        row.put("requester", req.getRequesterDisplayName());
        row.put("created", fmt.format(req.getCreated()));
        row.put("status", trsStatus(req, open, archived, itemStatuses, sentApps));
        row.put("items", items);
        rows.add(row);
    }
    return rows;
}

Field trsReadOnly(String name, String label, String value) {
    Field f = new Field();
    f.setName(name);
    f.setDisplayName(label);
    f.setType(Field.TYPE_STRING);
    f.setValue(value);
    f.setReadOnly(true);
    return f;
}

/**
 * The results form: filters, then one section per request.
 * viewAsManager is only honored when the launcher passes trsCanViewAs; otherwise it is the launcher's own team.
 */
Form trsBuildForm(String launcherName, String viewAsManager, String memberName) {
    boolean canViewAs = trsCanViewAs(launcherName);
    boolean viewingOther = canViewAs && !Util.isNullOrEmpty(viewAsManager) && !viewAsManager.equals(launcherName);
    String managerName = viewingOther ? viewAsManager : launcherName;

    List team = trsTeam(managerName);
    boolean memberInTeam = false;
    for (Object o : team) {
        if (((Map) o).get("name").equals(memberName)) {
            memberInTeam = true;
        }
    }
    if (!memberInTeam) {
        memberName = TRS_ALL;   // also resets the filter when the picked manager changes
    }

    Form form = new Form();
    form.setName("My Team's Requests");
    form.setPageTitle("My Team's Requests");

    Form.Section filter = new Form.Section();
    filter.setName("filter");
    String whose = viewingOther ? trsNameToDisplay(managerName) + "'s" : "your";
    filter.setLabel("Access requests for " + whose + " direct reports, last " + TRS_DAYS + " days");
    if (canViewAs) {
        Field manager = new Field();
        manager.setName("viewAsManager");
        manager.setDisplayName("View as manager");
        manager.setHelpKey("Admins only: see what this manager sees. Leave empty for your own team. Click Show after picking.");
        manager.setType("sailpoint.object.Identity");
        manager.setFilterString("managerStatus == true");
        manager.setAttribute("valueProperty", "name");
        manager.setValue(viewingOther ? managerName : null);
        filter.add(manager);
    }
    Field member = new Field();
    member.setName("teamMember");
    member.setDisplayName("Team member");
    member.setType(Field.TYPE_STRING);
    List allowed = new ArrayList();
    allowed.add(Arrays.asList(new Object[] { TRS_ALL, "All team members" }));
    for (Object o : team) {
        Map m = (Map) o;
        allowed.add(Arrays.asList(new Object[] { m.get("name"), m.get("displayName") }));
    }
    member.setAllowedValues(allowed);
    member.setValue(memberName);
    filter.add(member);
    form.add(filter);

    List rows = trsRequests(managerName, memberName);
    if (rows.isEmpty()) {
        Form.Section none = new Form.Section();
        none.setName("none");
        String empty;
        if (!team.isEmpty()) {
            empty = "No access requests in the last " + TRS_DAYS + " days.";
        } else if (viewingOther) {
            empty = "No one reports to " + trsNameToDisplay(managerName) + " in IdentityIQ.";
        } else if (canViewAs) {
            empty = "No one reports to you. Pick a manager in \"View as manager\" and click Show.";
        } else {
            empty = "No one reports to you in IdentityIQ.";
        }
        Field msg = trsReadOnly("noRequests", "Requests", empty);
        none.add(msg);
        form.add(none);
    }
    int n = 0;
    for (Object o : rows) {
        Map row = (Map) o;
        n++;
        Form.Section s = new Form.Section();
        s.setName("request" + n);
        s.setLabel("#" + row.get("id") + "  " + row.get("person") + "  (" + row.get("created") + ")");
        s.add(trsReadOnly("status" + n, "Status", (String) row.get("status")));
        s.add(trsReadOnly("requester" + n, "Requested by", (String) row.get("requester")));
        int i = 0;
        for (Object io : (List) row.get("items")) {
            Map im = (Map) io;
            i++;
            s.add(trsReadOnly("item" + n + "_" + i, (String) im.get("label"), (String) im.get("status")));
        }
        form.add(s);
    }

    List buttons = new ArrayList();
    Form.Button show = new Form.Button();
    show.setAction(Form.ACTION_NEXT);
    show.setLabel("Show");
    buttons.add(show);
    Form.Button close = new Form.Button();
    close.setAction(Form.ACTION_CANCEL);
    close.setLabel("Close");
    buttons.add(close);
    form.setButtons(buttons);
    return form;
}
